import math

def count_primes_up_to_n(n: int) -> int:
    if n < 2:
        return 0

    LIMIT = 1000000
    pList = [True] * (LIMIT + 1)
    pList[0] = pList[1] = False  # 0 and 1 are not prime numbers

    p = 2
    while p ** 2 <= LIMIT:
        if pList[p]:
            for i in range(p * 2, LIMIT + 1, p):
                pList[i] = False
        p += 1

    count = 0
    for i in range(2, n + 1):
        if pList[i]:
            count += 1

    return count

